const input = $input.first().json || {};
const rawSnippets = Array.isArray(input.snippets) ? input.snippets : [];
const sanitized = rawSnippets
  .map((snippet) => {
    const text = typeof snippet.text_redacted === 'string' ? snippet.text_redacted.replace(/\s+/g, ' ').trim() : '';
    const tone = typeof snippet.tone === 'string' ? snippet.tone.trim().toLowerCase() : 'mixed';
    if (!text || text.length < 12 || text.length > 280) {
      return null;
    }
    if (/[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(text) || /@[A-Za-z0-9_]+/.test(text) || /ห้อง\s*\d+/i.test(text)) {
      return null;
    }
    return {
      text_redacted: text,
      tone: ['low', 'mixed', 'positive'].includes(tone) ? tone : 'mixed',
      safety_notes: typeof snippet.safety_notes === 'string' ? snippet.safety_notes.trim() : null,
    };
  })
  .filter(Boolean)
  .slice(0, 3);
const sourceWindow = input.source_window && typeof input.source_window === 'object' ? input.source_window : {};
return {
  json: {
    class_id: input.class_id,
    week_start: input.week_start,
    source_window: sourceWindow,
    snippets: sanitized,
    snippet_count: sanitized.length,
    approval_status: 'approved',
    created_by_workflow: 'phase-c-redaction-batch',
    created_by_execution: input.created_by_execution || $execution.id,
  }
};

